def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > 300:
                rich_threat += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    low_supply = supply <= 17
    high_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if low_supply:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1
    if rich_threat >= 1:
        urgency += 1

    if urgency >= 6:
        bid = max(95.0, highest_prev + 2.0)
    elif urgency >= 4:
        bid = max(62.0, min(92.0, avg_prev + 3.0))
    elif urgency >= 2:
        bid = 38.0 if high_supply else 46.0
        if highest_prev < 60:
            bid = max(bid, highest_prev + 1.5)
    else:
        bid = 20.0 if high_supply else 26.0
        if day >= 8 and hp >= 6:
            bid = 16.0

    if highest_prev >= 140 and urgency <= 3:
        bid = min(bid, 28.0)

    reserve_target = 0.0
    days_left = max(0, 10 - day)
    if hp > 4:
        reserve_target = days_left * 18.0
    max_safe = max(0.0, budget - reserve_target)

    if urgency >= 4:
        final_bid = min(budget, max(bid, min(budget, max_safe + 20.0)))
    else:
        if max_safe > 0:
            final_bid = min(budget, min(bid, max_safe))
        else:
            final_bid = min(budget, 18.0 if hp > 4 else 40.0)

    if hp <= 2 or no_water_days >= 2:
        final_bid = min(budget, max(final_bid, highest_prev + 3.0, 88.0))

    if final_bid < 0:
        final_bid = 0.0

    return float(round(final_bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        target = min(my_status['budget'], avg_bid * 1.05)
        return max(target, DAILY_SALARY * 0.6)

    return min(my_status['budget'], DAILY_SALARY * 0.75)
